   270	        (m_asked == "password" && refused({"wrong_password", "too_many_tries"})) ||
   271	        (m_asked == "resend" && refused({"too_many_codes"}))) {
   272	        m_email.refusal    = refusal;
   273	        m_email.tries_left = body.value("tries_left", 0);
   274	        return std::nullopt;
   275	    }
   276	    return failed("sign_in_failed", "JusPrin couldn't sign you in. Try again.", true);
   277	}
   278	
   279	void CloudSignIn::cancel()
   280	{
   281	    if (m_phase == CloudSignInPhase::Browser && m_deps.cancel_authorize)
   282	        m_deps.cancel_authorize();
   283	    ++m_generation;
   284	    m_phase = CloudSignInPhase::Idle;
   285	    m_token.clear();
   286	    m_who.reset();
   287	    m_models.reset();
   288	}
   289	
   290	std::optional<CloudSignInOutcome> CloudSignIn::poll()
   291	{
   292	    if (m_deps.pump)
   293	        m_deps.pump();
   294	    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
   295	        if (item->generation != m_generation)
   296	            continue; // from a sign-in that was cancelled
   297	        switch (item->kind) {
   298	        case Inbox::Kind::Authorized:
   299	            if (m_phase != CloudSignInPhase::Browser)
   300	                continue;
   301	            if (!item->authorization.ok || item->authorization.access_token.empty())
   302	                return failed("sign_in_failed", "Signing in didn't finish. Nothing was saved. Try again.", true);
   303	            begin_check(std::move(item->authorization.access_token));
   304	            break;
   305	        case Inbox::Kind::Auth:
   306	            if (m_phase != CloudSignInPhase::Email)
   307	                continue;
   308	            if (std::optional<CloudSignInOutcome> outcome = answered(std::move(item->http)))
   309	                return outcome;
   310	            break;
   311	        case Inbox::Kind::Who: m_who = std::move(item->http); break;
   312	        case Inbox::Kind::Models: m_models = std::move(item->http); break;
   313	        }
   314	        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
   315	            return finish_check();
   316	    }
   317	    return std::nullopt;
   318	}
   319	
   320	std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
   321	{
   322	    const CloudHttpResult who    = std::move(*m_who);
   323	    const CloudHttpResult models = std::move(*m_models);
   324	    m_who.reset();
   325	    m_models.reset();
   326	    if (refused(who) || refused(models)) {
   327	        m_phase = CloudSignInPhase::Idle;
   328	        m_token.clear();
   329	        CloudSignInOutcome outcome;
   330	        outcome.kind = CloudSignInOutcome::Kind::Expired;
   331	        return outcome;
   332	    }
   333	    const json who_json    = json::parse(who.body, nullptr, false);
   334	    const json models_json = json::parse(models.body, nullptr, false);
   335	    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
   336	        !models_json.contains("data"))
   337	        return failed("account_unreachable", "JusPrin couldn't be reached to finish signing in. Try again.", true);
   338	
   339	    CloudAccountRecord record;
   340	    record.token = m_token;
   341	    // /jusprin/api/me/ answers {"user": {"email", ...}, "ai_credits": {...}}.
   342	    record.email = who_json.value("/user/email"_json_pointer, std::string());
   343	    for (const json& entry : models_json["data"]) {
   344	        const std::string id = entry.value("id", ""), format = entry.value("format", "");
   345	        if (!id.empty() && !format.empty())
   346	            record.formats.emplace_back(id, format);
   347	    }
   348	    // The agent is for the provider's default model, or else the first the
   349	    // server lists.
   350	    auto chosen = std::find_if(record.formats.begin(), record.formats.end(),
   351	                               [this](const auto& entry) { return entry.first == m_default_model; });
   352	    if (chosen == record.formats.end())
   353	        chosen = record.formats.begin();
   354	    AgentServicePtr service = chosen == record.formats.end() ? nullptr : m_agents(m_token, chosen->first, chosen->second);
   355	    if (!service)
   356	        return failed("account_no_models", "JusPrin has no Agent model for this account right now. Try again later.", true);
   357	
   358	    CloudSignInOutcome outcome;
   359	    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
   360	    outcome.email   = record.email;
   361	    outcome.saved   = m_store.save && m_store.save(record);
   362	    outcome.service = std::move(service);
   363	    m_phase         = CloudSignInPhase::Idle;
   364	    m_token.clear();
   365	    return outcome;
   366	}
   367	
   368	CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
   369	{
   370	    m_phase = CloudSignInPhase::Idle;
   371	    m_token.clear();
   372	    CloudSignInOutcome outcome;
   373	    outcome.kind  = CloudSignInOutcome::Kind::Failed;
   374	    outcome.error = AgentError{code, message, retryable};
   375	    return outcome;
   376	}
   377	
   378	std::optional<CloudAccountRecord> CloudSignIn::account() const
   379	{
   380	    if (!m_store.load)
   381	        return std::nullopt;
   382	    std::optional<CloudAccountRecord> record = m_store.load();
   383	    if (!record || record->token.empty())
   384	        return std::nullopt;
   385	    return record;
   386	}
   387	
   388	bool CloudSignIn::sign_out()
   389	{
   390	    const std::optional<CloudAccountRecord> record = account();
   391	    if (!record || !m_store.erase || !m_store.erase())
   392	        return false;
   393	    cancel();
   394	    if (m_deps.revoke)
   395	        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
   396	    return true;
   397	}
