     1	// The first launch: the welcome, then the Printers step. Each screen is the
     2	// board of the same name on the "JusPrin v2" canvas's "On boarding
     3	// experience" page (first-run-welcome-01, first-run-04 to 08). The host
     4	// decides which is in front (Home/OnboardingModel) and carries out every
     5	// door; this file only draws them.
     6	//
     7	// Every door on the welcome comes back into the sequence: signing in waits on
     8	// the offer card, Preferences closes back onto the welcome, and "Just slice
     9	// for now" moves on at once.
    10	
    11	import { useEffect, useRef, useState } from 'react';
    12	import type { Appearance, EmailSignIn, ImportResultItem, OnboardingState } from '../bridge/protocol';
    13	import { creditCount } from '../../../AgentUI/src/credits';
    14	import lockupLight from '@resources/jusprin/overlay/images/OrcaSlicer_horizontal_light.svg';
    15	import lockupDark from '@resources/jusprin/overlay/images/OrcaSlicer_horizontal_dark.svg';
    16	import clip from '@resources/jusprin/welcome/welcome-clip.mp4';
    17	import googleMark from '@resources/jusprin/welcome/google-g.svg';
    18	import { CodeField } from './CodeField';
    19	import { CheckGlyph, FolderGlyph, PrinterGlyph, WarningGlyph } from './Glyphs';
    20	import { PrinterFormHost } from './PrinterFormHost';
    21	
    22	// How long the card says who signed in before the Printers step.
    23	const SIGNED_IN_PAUSE_MS = 1500;
    24	
    25	type Action = (type: string, payload?: object) => void;
    26	
    27	interface Props {
    28	  onboarding: OnboardingState;
    29	  appearance: Appearance;
    30	  error?: string;
    31	  onAction: Action;
    32	}
    33	
    34	// The JusPrin lockup in the window's top-left corner, as the welcome boards
    35	// anchor it; the welcome has no header of its own.
    36	function Lockup({ appearance }: { appearance: Appearance }) {
    37	  return <img className="onboarding-lockup" src={appearance === 'dark' ? lockupDark : lockupLight} alt="JusPrin" />;
    38	}
    39	
    40	// What the server's refusal means to the person.
    41	function refusalText(email: EmailSignIn): string {
    42	  switch (email.refusal) {
    43	    case 'wrong_code':
    44	      return `That code is wrong. ${email.triesLeft} ${email.triesLeft === 1 ? 'try' : 'tries'} left.`;
    45	    case 'expired_code':
    46	      return 'That code has expired. We can send a new one.';
    47	    case 'too_many_tries':
    48	      return email.step === 'password'
    49	        ? 'Too many tries. Try again in an hour, or email me a code.'
    50	        : 'Too many wrong tries for this code. We can send a new one.';
    51	    case 'too_many_codes':
    52	      return 'Too many codes were sent to this address. Try again in an hour.';
    53	    case 'wrong_password':
    54	      return 'That password is wrong.';
    55	    default:
    56	      return '';
    57	  }
    58	}
    59	
    60	// Links in a row, separated by middle dots, with Cancel apart on the right.
    61	function LinkRow({ links, cancel }: { links: [string, () => void][]; cancel?: () => void }) {
    62	  return (
    63	    <div className="onboarding-link-row">
    64	      <span className="onboarding-links">
    65	        {links.map(([label, onClick], index) => (
    66	          <span key={label}>
    67	            {index > 0 && <span className="onboarding-link-dot" aria-hidden="true">·</span>}
    68	            <button type="button" className="onboarding-link flush" onClick={onClick}>{label}</button>
    69	          </span>
    70	        ))}
    71	      </span>
    72	      {cancel && <button type="button" className="onboarding-link flush" onClick={cancel}>Cancel</button>}
    73	    </div>
    74	  );
    75	}
    76	
    77	// The email door's code step (boards 12b and 12c).
    78	function CodeStep({ email, onAction, onChangeEmail, onBrowser }: {
    79	  email: EmailSignIn; onAction: Action; onChangeEmail: () => void; onBrowser: () => void;
    80	}) {
    81	  const [code, setCode] = useState('');
    82	  const field = useRef<HTMLInputElement>(null);
