    case Agent::CloudSignInPhase::Email: state.sign_in = "email"; break;
    case Agent::CloudSignInPhase::Checking: state.sign_in = "checking"; break;
    case Agent::CloudSignInPhase::Idle: state.sign_in = "idle"; break;
