    for (const fs::directory_entry& entry : fs::directory_iterator(account_folder / kPrinterFolder, error)) {
        if (entry.path().extension() != ".json")
            continue;
        if (const std::optional<nlohmann::json> json = read_config(entry.path()))
            if (std::string base = string_value(*json, "inherits"); !base.empty())
