void OrcaHomeBackend::install_ticked_printers(std::vector<OrcaImportItem>& items)
{
    Plater*    plater = wxGetApp().plater();
    AppConfig* config = wxGetApp().app_config;
    if (plater == nullptr || config == nullptr)
        throw std::logic_error("Home installed printers before the app finished starting");
    const Printers::VendorMap before    = config->vendors();
    bool                      installed = false;
    for (OrcaImportItem& item : items) {
        const std::vector<PrinterSetup::PrinterCandidate>& candidates = profile_catalog().candidates();
        const auto profile = std::find_if(candidates.begin(), candidates.end(), [&item](const PrinterSetup::PrinterCandidate& candidate) {
            return candidate.vendor_id == item.vendor && candidate.model_id == item.model && candidate.variant == item.nozzle;
        });
        if (profile == candidates.end())
            throw std::logic_error("A printer ticked in OrcaSlicer lost its JusPrin profile between detection and import");
        // The reason is the generic one: installing a shipped profile fails
        // only on a broken install, which the log describes.
        std::string problem;
        if (SetupCommands::install_and_select_printer(*plater, item.vendor, item.model, item.nozzle, profile->default_material, problem)) {
            item.outcome = OrcaImportItem::Outcome::Imported;
            item.reason  = OrcaImportItem::Reason::None;
            installed    = true;
        } else {
            BOOST_LOG_TRIVIAL(error) << "Installing " << item.model << " from OrcaSlicer's printer list failed: " << problem;
            item.outcome = OrcaImportItem::Outcome::NotImported;
            item.reason  = OrcaImportItem::Reason::NotLoaded;
        }
    }
    if (!installed)
        return;
    // Saved under their own names like any other printer installed here.
    Printers::name_installed_printers(*plater, before);
    printer_chosen();
}

