874	std::vector<OrcaImportItem> OrcaHomeBackend::bring_orca_items(std::vector<OrcaImportItem> ticked, const std::vector<std::string>& files)
875	{
876	    // Whichever kind holds OrcaSlicer's selected printer goes last, so its
877	    // selection is the one left. Otherwise the saved presets go last: the
878	    // first of them is the first printer the result lists.
879	    const bool selected_ticked = std::any_of(ticked.begin(), ticked.end(),
880	                                             [this](const OrcaImportItem& item) { return item.name == m_orca_selected; });
881	    if (!selected_ticked)
882	        install_ticked_printers(ticked, m_orca_selected);
883	    std::vector<OrcaImportItem> items = import_orca_files(files, m_orca_selected);
884	    if (selected_ticked)
885	        install_ticked_printers(ticked, m_orca_selected);
886	    items.insert(items.end(), std::make_move_iterator(ticked.begin()), std::make_move_iterator(ticked.end()));
887	    return items;
