890	void OrcaHomeBackend::retry_orca_import()
891	{
892	    if (!m_import_result)
893	        throw std::logic_error("Home retried an OrcaSlicer import with no result on screen");
894	    // A failed ticked printer is installed again; a failed file is imported again.
895	    std::vector<OrcaImportItem> ticked;
896	    std::vector<std::string>    failed;
897	    for (const OrcaImportItem& item : *m_import_result)
898	        if (item.outcome == OrcaImportItem::Outcome::NotImported) {
899	            if (item.vendor.empty())
900	                failed.push_back(item.source);
901	            else
902	                ticked.push_back(item);
903	        }
904	    // Each failed item is replaced by its new outcome, in place.
905	    // bring_orca_items lists the files' items before the ticked ones.
906	    std::vector<OrcaImportItem> again = bring_orca_items(std::move(ticked), failed);
907	    auto next_file   = again.begin();
908	    auto next_ticked = again.begin() + std::ptrdiff_t(failed.size());
909	    for (OrcaImportItem& item : *m_import_result)
910	        if (item.outcome == OrcaImportItem::Outcome::NotImported)
911	            item = item.vendor.empty() ? std::move(*next_file++) : std::move(*next_ticked++);
912	}
