949	void OrcaHomeBackend::install_ticked_printers(std::vector<OrcaImportItem>& items, const std::string& preferred)
950	{
951	    Plater* plater = wxGetApp().plater();
952	    if (plater == nullptr)
953	        throw std::logic_error("Home installed printers before the app finished starting");
954	    if (items.empty())
955	        return;
956	    bool installed = false;
957	    // Each printer is saved under its model's name as it is installed, two
958	    // nozzles of one model as two printers, and the last one saved stays
959	    // selected: the preferred one, otherwise the first, goes last.
960	    std::vector<OrcaImportItem*> order;
961	    for (OrcaImportItem& item : items)
962	        order.push_back(&item);
963	    const auto kept = std::find_if(order.begin(), order.end(), [&](const OrcaImportItem* item) { return item->name == preferred; });
964	    std::rotate(order.begin(), kept == order.end() ? order.begin() + 1 : kept + 1, order.end());
965	    for (OrcaImportItem* entry : order) {
966	        OrcaImportItem& item = *entry;
967	        const std::vector<PrinterSetup::PrinterCandidate>& candidates = profile_catalog().candidates();
968	        const auto profile = std::find_if(candidates.begin(), candidates.end(), [&item](const PrinterSetup::PrinterCandidate& candidate) {
969	            return candidate.vendor_id == item.vendor && candidate.model_id == item.model && candidate.variant == item.nozzle;
970	        });
971	        if (profile == candidates.end())
972	            throw std::logic_error("A printer ticked in OrcaSlicer lost its JusPrin profile between detection and import");
973	        // The reason is the generic one: installing a shipped profile fails
974	        // only on a broken install, which the log describes.
975	        std::string problem;
976	        if (SetupCommands::install_and_select_printer(*plater, item.vendor, item.model, item.nozzle, profile->default_material, problem)) {
977	            Printers::add_named_printer(*plater, item.model, {});
978	            item.outcome = OrcaImportItem::Outcome::Imported;
979	            item.reason  = OrcaImportItem::Reason::None;
980	            installed    = true;
981	        } else {
982	            BOOST_LOG_TRIVIAL(error) << "Installing " << item.model << " from OrcaSlicer's printer list failed: " << problem;
983	            item.outcome = OrcaImportItem::Outcome::NotImported;
984	            item.reason  = OrcaImportItem::Reason::NotLoaded;
985	        }
986	    }
987	    if (installed)
988	        printer_chosen();
989	}
