991	std::vector<OrcaImportItem> OrcaHomeBackend::import_orca_files(const std::vector<std::string>& files, const std::string& preferred)
992	{
993	    namespace fs = std::filesystem;
994	    PresetBundle* presets = wxGetApp().preset_bundle;
995	    AppConfig* config     = wxGetApp().app_config;
996	    Plater* plater        = wxGetApp().plater();
997	    if (presets == nullptr || config == nullptr || plater == nullptr)
998	        throw std::logic_error("Home imported printers before the app finished starting");
999	
1000	    OrcaImportCatalog catalog;
1001	    catalog.has = [presets](OrcaImportItem::Kind kind, const std::string& name) {
1002	        return preset_collection(*presets, kind).find_preset(name, false) != nullptr;
1003	    };
1004	    catalog.has_base = [presets](OrcaImportItem::Kind kind, const std::string& base) {
1005	        return preset_collection(*presets, kind).find_preset2(base, true) != nullptr;
1006	    };
1007	    // Renamed copies live here only until import_presets has copied them.
1008	    const fs::path staging = fs::temp_directory_path() / ("jusprin-orca-import-" + std::to_string(wxGetProcessId()));
1009	    fs::remove_all(staging);
1010	    fs::create_directories(staging);
1011	    std::vector<OrcaImportItem> items = plan_orca_import(files, catalog, staging);
1012	
1013	    std::vector<std::string> pending;
1014	    for (const OrcaImportItem& item : items)
1015	        if (item.outcome == OrcaImportItem::Outcome::Pending)
1016	            pending.push_back(item.file);
1017	    if (!pending.empty()) {
1018	        // Every taken name was renamed above, so import_presets has nothing
1019	        // to ask. Were it asked, the answer is no and that item says it was
1020	        // not imported.
1021	        presets->import_presets(pending, [](const std::string&) { return 0; }, ForwardCompatibilitySubstitutionRule::Enable,
1022	                                *config);
1023	        wxGetApp().load_current_presets();
1024	        presets->update_compatible(PresetSelectCompatibleType::Always);
1025	        m_frame.update_side_preset_ui();
1026	    }
1027	    // import_presets leaves in `pending` what it imported.
1028	    settle_orca_import(items, pending);
1029	    fs::remove_all(staging);
1030	
1031	    const auto is_printer = [](const OrcaImportItem& item) {
1032	        return item.kind == OrcaImportItem::Kind::Printer && item.outcome == OrcaImportItem::Outcome::Imported;
1033	    };
1034	    auto chosen = std::find_if(items.begin(), items.end(), [&](const OrcaImportItem& item) { return is_printer(item) && item.name == preferred; });
1035	    if (chosen == items.end())
1036	        chosen = std::find_if(items.begin(), items.end(), is_printer);
1037	    if (chosen != items.end()) {
1038	        SetupCommands::select_printer_preset(*plater, chosen->renamed_to.empty() ? chosen->name : chosen->renamed_to);
1039	        printer_chosen();
1040	    }
1041	    return items;
1042	}
