1044	std::vector<Snapshot::Onboarding::ImportItem> OrcaHomeBackend::import_result_lines(const std::vector<OrcaImportItem>& items)
1045	{
1046	    using Reason = OrcaImportItem::Reason;
1047	    std::vector<Snapshot::Onboarding::ImportItem> lines;
1048	    for (const OrcaImportItem& item : items) {
1049	        Snapshot::Onboarding::ImportItem line{to_string(item.kind), item.name, item.renamed_to,
1050	                                              item.outcome == OrcaImportItem::Outcome::Imported, {}};
1051	        switch (item.reason) {
1052	        case Reason::Unreadable: line.reason = utf8(_L("the file couldn't be read")); break;
1053	        case Reason::NoVersion: line.reason = utf8(_L("the file has no version")); break;
1054	        case Reason::NotAPreset: line.reason = utf8(_L("it isn't a printer, filament or process preset")); break;
1055	        case Reason::MissingBase:
1056	            line.reason = utf8(wxString::Format(_L("its base profile, %s, isn't in JusPrin"), wxString::FromUTF8(item.base)));
1057	            break;
1058	        case Reason::NotLoaded: line.reason = utf8(_L("JusPrin couldn't load it")); break;
1059	        case Reason::None: break;
1060	        }
1061	        lines.push_back(std::move(line));
1062	    }
1063	    return lines;
1064	}
